begin;

-- ───────────────── 20261111090000_core_schema.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- TH EDU Companion — core schema
--   categories · branches · videos · portfolios · leads
-- Column names follow the API spec; extra columns marked (+) support the app UI.
-- ═══════════════════════════════════════════════════════════════════════════

-- gen_random_uuid() is built into Postgres 13+ (Supabase runs 15+), so no extension needed.

-- ─── Shared trigger: keep updated_at fresh ──────────────────────────────────
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ─── categories ─────────────────────────────────────────────────────────────
create table public.categories (
  id          smallint generated always as identity primary key,
  code        text not null unique check (code ~ '^[A-Z_]+$'),
  name        text not null,
  icon        text not null,                         -- lucide icon name, e.g. 'pencil-line'
  color       text not null default '#2F6BFF',       -- (+) chip / badge colour
  sort_order  smallint not null default 0            -- (+)
);

comment on table public.categories is 'Course subjects. "ALL" is a UI filter, not a row.';

-- ─── branches (+) ───────────────────────────────────────────────────────────
-- Not in the original spec, but leads/portfolios reference a branch and notifications
-- need its address + map link; a lookup table keeps that data in one place.
create table public.branches (
  code           text primary key check (code ~ '^[A-Z_]+$'),   -- 'XA_LA', 'NGO_THI_NHAM'
  short_code     text not null unique,                          -- 'CS1', 'CS2'
  name           text not null,
  short_address  text not null,
  address        text not null,
  maps_url       text not null
);

-- ─── videos ─────────────────────────────────────────────────────────────────
create table public.videos (
  id                  uuid primary key default gen_random_uuid(),
  title               text not null check (char_length(title) between 3 and 200),
  video_url           text not null check (video_url ~ '^https://'),
  thumbnail_url       text not null check (thumbnail_url ~ '^https://'),
  category_code       text not null references public.categories (code) on update cascade,
  teacher_name        text not null,
  cta_text            text not null,
  created_at          timestamptz not null default now(),

  teacher_avatar_url  text,                                     -- (+)
  tags                text[] not null default '{}',             -- (+) '#ToanTuDuy', …
  cta_link            text,                                     -- (+) thedu://booking?course=…
  is_published        boolean not null default true,            -- (+)
  published_at        timestamptz not null default now(),       -- (+) feed sort key
  updated_at          timestamptz not null default now()        -- (+)
);

-- Keyset pagination: newest first, optionally per category.
create index videos_feed_idx      on public.videos (published_at desc, id desc) where is_published;
create index videos_feed_cat_idx  on public.videos (category_code, published_at desc, id desc) where is_published;

create trigger videos_updated_at before update on public.videos
  for each row execute function public.set_updated_at();

-- ─── portfolios ─────────────────────────────────────────────────────────────
create table public.portfolios (
  id                  uuid primary key default gen_random_uuid(),
  student_name        text not null,
  course_code         text not null references public.categories (code) on update cascade,
  branch_location     text not null references public.branches (code) on update cascade,
  before_image_url    text not null check (before_image_url ~ '^https://'),
  after_image_url     text not null check (after_image_url ~ '^https://'),
  teacher_note        text not null,
  created_at          timestamptz not null default now(),

  display_name        text not null,                            -- (+) 'Bé Gia Bảo'
  class_name          text not null default '',                 -- (+) 'Lớp 1'
  before_label        text not null default 'TRƯỚC',            -- (+) slider overlay
  after_label         text not null default 'SAU',              -- (+)
  teacher_name        text not null,                            -- (+)
  teacher_avatar_url  text,                                     -- (+)
  assessments         jsonb not null default '[]'               -- (+) [{skill, before, after}]
                        check (jsonb_typeof(assessments) = 'array'),
  duration_label      text not null default '',                 -- (+) '2 tháng'
  -- Children's names and work are personal data: never public without written parent consent.
  parent_consent      boolean not null default false,           -- (+)
  is_published        boolean not null default false,           -- (+)
  updated_at          timestamptz not null default now()        -- (+)
);

create index portfolios_public_idx on public.portfolios (course_code, created_at desc)
  where is_published and parent_consent;

create trigger portfolios_updated_at before update on public.portfolios
  for each row execute function public.set_updated_at();

-- ─── leads ──────────────────────────────────────────────────────────────────
create type public.lead_status as enum ('NEW', 'CONTACTED', 'ENROLLED');

create table public.leads (
  id                 uuid primary key default gen_random_uuid(),   -- client may supply → idempotency key
  parent_name        text not null check (char_length(btrim(parent_name)) between 2 and 60),
  phone_number       text not null check (phone_number ~ '^0[35789][0-9]{8}$'),  -- normalised 0xxxxxxxxx
  student_name       text not null check (char_length(btrim(student_name)) between 2 and 60),
  student_age        smallint not null check (student_age between 3 and 12),
  course_code        text not null references public.categories (code) on update cascade,
  branch_location    text not null references public.branches (code) on update cascade,
  quiz_summary       jsonb check (quiz_summary is null or jsonb_typeof(quiz_summary) = 'object'),
  status             public.lead_status not null default 'NEW',
  created_at         timestamptz not null default now(),

  -- (+) human booking code, same formula as the app: 'TH-' + last 6 hex of the uuid
  code               text generated always as ('TH-' || upper(right(replace(id::text, '-', ''), 6))) stored,
  preferred_date     date,                                             -- (+)
  preferred_slot     text,                                             -- (+) slot id, e.g. 'wd-1730'
  source             text not null default 'DIRECT'
                       check (source in ('FEED', 'QUIZ', 'PORTFOLIO', 'DIRECT')),  -- (+)
  zalo_user_id       text,                                             -- (+)
  quiz_answers       jsonb,                                            -- (+)
  notified_at        timestamptz,                                      -- (+) set by the api function
  notification_log   jsonb,                                            -- (+)
  updated_at         timestamptz not null default now()                -- (+)
);

create index leads_created_at_idx   on public.leads (created_at desc);
create index leads_phone_recent_idx on public.leads (phone_number, created_at desc);
create index leads_status_idx       on public.leads (status) where status <> 'ENROLLED';
create index leads_code_idx         on public.leads (code);   -- not unique: 6 hex chars can collide

create trigger leads_updated_at before update on public.leads
  for each row execute function public.set_updated_at();

-- ───────────────── 20261111090100_rls_policies.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Row Level Security
--   • Public (anon + authenticated) READ: categories, branches, published videos,
--     published + consented portfolios.
--   • Public INSERT: leads (NEW only). No public read/update/delete of leads.
--   • Staff (JWT app_metadata.role = 'staff') can read & update leads, manage content.
-- ═══════════════════════════════════════════════════════════════════════════

alter table public.categories  enable row level security;
alter table public.branches    enable row level security;
alter table public.videos      enable row level security;
alter table public.portfolios  enable row level security;
alter table public.leads       enable row level security;

-- Helper: is the caller a centre staff member? (set via auth.users.raw_app_meta_data)
create or replace function public.is_staff()
returns boolean
language sql
stable
as $$
  select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') = 'staff', false);
$$;

-- ─── Public read ────────────────────────────────────────────────────────────
create policy "public read categories"
  on public.categories for select to anon, authenticated
  using (true);

create policy "public read branches"
  on public.branches for select to anon, authenticated
  using (true);

create policy "public read published videos"
  on public.videos for select to anon, authenticated
  using (is_published and published_at <= now());

create policy "public read consented portfolios"
  on public.portfolios for select to anon, authenticated
  using (is_published and parent_consent);

-- ─── Public lead capture ────────────────────────────────────────────────────
-- Prefer the `api` Edge Function (validation, rate limit, notifications); this policy
-- allows direct PostgREST inserts as the spec requires, but only "fresh" rows.
create policy "public insert leads"
  on public.leads for insert to anon, authenticated
  with check (
    status = 'NEW'
    and notified_at is null
    and notification_log is null
    and (preferred_date is null or preferred_date >= current_date)
  );

-- ─── Staff ──────────────────────────────────────────────────────────────────
create policy "staff read leads"
  on public.leads for select to authenticated
  using (public.is_staff());

create policy "staff update leads"
  on public.leads for update to authenticated
  using (public.is_staff())
  with check (public.is_staff());

create policy "staff manage videos"
  on public.videos for all to authenticated
  using (public.is_staff())
  with check (public.is_staff());

create policy "staff manage portfolios"
  on public.portfolios for all to authenticated
  using (public.is_staff())
  with check (public.is_staff());

-- ─── Column privileges ──────────────────────────────────────────────────────
-- RLS limits rows; grants limit columns. Anonymous clients may only write lead input fields.
revoke insert, update, delete on public.leads from anon;
grant insert (id, parent_name, phone_number, student_name, student_age, course_code, branch_location,
              quiz_summary, preferred_date, preferred_slot, source, zalo_user_id, quiz_answers)
  on public.leads to anon;
revoke select on public.leads from anon;

-- ───────────────── 20261111090200_functions.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Database functions (callable via PostgREST RPC and from the `api` Edge Function)
--   get_feed(category, limit, cursor)  → keyset-paginated published videos
--   submit_lead(payload jsonb)         → validated, idempotent, rate-limited lead insert
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── get_feed ───────────────────────────────────────────────────────────────
-- SECURITY INVOKER: RLS on videos still applies (only published rows).
-- Cursor = (published_at, id) of the last item from the previous page.
create or replace function public.get_feed(
  p_category_code   text        default null,
  p_limit           int         default 10,
  p_before_ts       timestamptz default null,
  p_before_id       uuid        default null
)
returns setof public.videos
language sql
stable
security invoker
set search_path = public
as $$
  select v.*
  from public.videos v
  where v.is_published
    and v.published_at <= now()
    and (p_category_code is null or v.category_code = p_category_code)
    and (
      p_before_ts is null
      or (v.published_at, v.id) < (p_before_ts, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid))
    )
  order by v.published_at desc, v.id desc
  limit least(greatest(coalesce(p_limit, 10), 1), 50);
$$;

grant execute on function public.get_feed(text, int, timestamptz, uuid) to anon, authenticated;

-- ─── submit_lead ────────────────────────────────────────────────────────────
-- SECURITY DEFINER so it can check duplicates / rate limits without granting anon SELECT on leads.
-- Errors are raised with stable SQLSTATE-style hints the API maps to HTTP codes:
--   'VALIDATION:<field>'  → 422,  'RATE_LIMITED' → 429
create or replace function public.submit_lead(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id           uuid := coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid());
  v_phone        text := regexp_replace(coalesce(p ->> 'phone_number', ''), '[\s.()-]', '', 'g');
  v_parent       text := btrim(coalesce(p ->> 'parent_name', ''));
  v_student      text := btrim(coalesce(p ->> 'student_name', ''));
  v_age          int;
  v_course       text := p ->> 'course_code';
  v_branch       text := p ->> 'branch_location';
  v_date         date;
  v_existing     public.leads;
  v_row          public.leads;
  v_recent_count int;
begin
  -- Normalise +84xxxxxxxxx → 0xxxxxxxxx
  if v_phone like '+84%' then
    v_phone := '0' || substr(v_phone, 4);
  end if;

  -- Validation (mirrors table CHECKs, but with field-level messages)
  if v_phone !~ '^0[35789][0-9]{8}$' then
    raise exception 'Số điện thoại không hợp lệ' using hint = 'VALIDATION:phone_number';
  end if;
  if char_length(v_parent) not between 2 and 60 or v_parent ~ '[0-9]' then
    raise exception 'Họ tên phụ huynh không hợp lệ' using hint = 'VALIDATION:parent_name';
  end if;
  if char_length(v_student) not between 2 and 60 or v_student ~ '[0-9]' then
    raise exception 'Họ tên của bé không hợp lệ' using hint = 'VALIDATION:student_name';
  end if;
  begin
    v_age := (p ->> 'student_age')::int;
  exception when others then
    v_age := null;
  end;
  if v_age is null or v_age not between 3 and 12 then
    raise exception 'Tuổi của bé không hợp lệ' using hint = 'VALIDATION:student_age';
  end if;
  if not exists (select 1 from public.categories where code = v_course) then
    raise exception 'Khóa học không tồn tại' using hint = 'VALIDATION:course_code';
  end if;
  if not exists (select 1 from public.branches where code = v_branch) then
    raise exception 'Cơ sở không tồn tại' using hint = 'VALIDATION:branch_location';
  end if;
  if p ? 'preferred_date' and nullif(p ->> 'preferred_date', '') is not null then
    v_date := (p ->> 'preferred_date')::date;
    if v_date < current_date or v_date > current_date + 60 then
      raise exception 'Ngày học thử không hợp lệ' using hint = 'VALIDATION:preferred_date';
    end if;
  end if;

  -- Idempotency: same client-generated id → return the original row.
  select * into v_existing from public.leads where id = v_id;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  -- Double-submit guard: same phone + child + course within 30 minutes.
  select * into v_existing
  from public.leads
  where phone_number = v_phone
    and course_code = v_course
    and lower(student_name) = lower(v_student)
    and created_at > now() - interval '30 minutes'
  order by created_at desc
  limit 1;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  -- Abuse guard: at most 5 leads per phone per 24h.
  select count(*) into v_recent_count
  from public.leads
  where phone_number = v_phone and created_at > now() - interval '24 hours';
  if v_recent_count >= 5 then
    raise exception 'Số điện thoại này đã đăng ký nhiều lần hôm nay' using hint = 'RATE_LIMITED';
  end if;

  insert into public.leads (
    id, parent_name, phone_number, student_name, student_age, course_code, branch_location,
    quiz_summary, preferred_date, preferred_slot, source, zalo_user_id, quiz_answers
  ) values (
    v_id, v_parent, v_phone, v_student, v_age, v_course, v_branch,
    p -> 'quiz_summary',
    v_date,
    nullif(p ->> 'preferred_slot', ''),
    coalesce(nullif(p ->> 'source', ''), 'DIRECT'),
    nullif(p ->> 'zalo_user_id', ''),
    p -> 'quiz_answers'
  )
  returning * into v_row;

  return jsonb_build_object('id', v_row.id, 'code', v_row.code,
                            'created_at', v_row.created_at, 'duplicate', false);
end;
$$;

revoke all on function public.submit_lead(jsonb) from public;
grant execute on function public.submit_lead(jsonb) to anon, authenticated, service_role;

-- ───────────────── 20261112090000_trust.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Trust & social proof — every public claim is backed by data staff control.
--   trust_stats      verified stats; a source note is REQUIRED to publish
--   testimonials     parent videos / letters / notebooks; consent REQUIRED to publish
--   recent_activity  anonymised feed of real recent bookings (powers the TrustTicker)
--   leads.promo_code incentive claimed in the app (e.g. exit-intent e-book)
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── trust_stats ────────────────────────────────────────────────────────────
create table public.trust_stats (
  id            uuid primary key default gen_random_uuid(),
  icon          text not null,                    -- emoji, e.g. '⭐'
  headline      text,                             -- '98%' (null for qualitative claims)
  label         text not null,                    -- 'học sinh cải thiện nét chữ sau 1 tháng'
  source_note   text not null default '',         -- 'Đánh giá đầu vào/ra của 126 HS, T6–T9/2026'
  measured_on   date,
  sort_order    smallint not null default 0,
  is_published  boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  -- A stat cannot go live without saying where it comes from.
  constraint trust_stats_source_required check (not is_published or char_length(btrim(source_note)) >= 10)
);

create trigger trust_stats_updated_at before update on public.trust_stats
  for each row execute function public.set_updated_at();

-- ─── testimonials ───────────────────────────────────────────────────────────
create table public.testimonials (
  id                 uuid primary key default gen_random_uuid(),
  kind               text not null check (kind in ('VIDEO', 'LETTER', 'NOTEBOOK')),
  parent_label       text not null,                       -- 'Mẹ bé Gia Bảo' — as approved by the parent
  course_code        text not null references public.categories (code) on update cascade,
  branch_location    text references public.branches (code) on update cascade,
  quote              text not null default '',
  media_url          text not null check (media_url ~ '^https://'),
  thumbnail_url      text check (thumbnail_url is null or thumbnail_url ~ '^https://'),
  duration_sec       int check (duration_sec is null or duration_sec > 0),
  recorded_on        date,
  -- Written consent from the parent to publish (name, child's work, face/voice).
  consent_confirmed  boolean not null default false,
  is_published       boolean not null default false,
  sort_order         smallint not null default 0,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint testimonials_consent_required check (not is_published or consent_confirmed),
  constraint testimonials_video_thumb check (kind <> 'VIDEO' or thumbnail_url is not null)
);

create index testimonials_public_idx on public.testimonials (kind, sort_order, created_at desc)
  where is_published and consent_confirmed;

create trigger testimonials_updated_at before update on public.testimonials
  for each row execute function public.set_updated_at();

-- ─── RLS ────────────────────────────────────────────────────────────────────
alter table public.trust_stats  enable row level security;
alter table public.testimonials enable row level security;

create policy "public read published stats"
  on public.trust_stats for select to anon, authenticated
  using (is_published);

create policy "public read consented testimonials"
  on public.testimonials for select to anon, authenticated
  using (is_published and consent_confirmed);

create policy "staff manage stats"
  on public.trust_stats for all to authenticated
  using (public.is_staff()) with check (public.is_staff());

create policy "staff manage testimonials"
  on public.testimonials for all to authenticated
  using (public.is_staff()) with check (public.is_staff());

-- ─── leads.promo_code ───────────────────────────────────────────────────────
alter table public.leads
  add column promo_code text check (promo_code is null or promo_code in ('EBOOK_VAO_LOP_1'));

grant insert (promo_code) on public.leads to anon;

-- ─── recent_activity: anonymised real bookings ──────────────────────────────
-- SECURITY DEFINER so the public can see *that* bookings happen without reading leads.
-- Exposes only: masked label ("Phụ huynh T."), course, branch, time. No ids, phones or child data.
create or replace function public.recent_activity(p_limit int default 12)
returns table (
  actor_label  text,
  course_code  text,
  course_name  text,
  branch_code  text,
  branch_name  text,
  created_at   timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select
    'Phụ huynh ' || upper(left(
      (string_to_array(btrim(l.parent_name), ' '))[array_length(string_to_array(btrim(l.parent_name), ' '), 1)],
      1)) || '.' as actor_label,
    l.course_code,
    c.name,
    l.branch_location,
    b.name,
    -- Round to 5 minutes: enough for "x phút trước", not enough to pinpoint someone.
    date_trunc('hour', l.created_at) + floor(extract(minute from l.created_at) / 5) * interval '5 minutes'
  from public.leads l
  join public.categories c on c.code = l.course_code
  join public.branches b on b.code = l.branch_location
  where l.created_at > now() - interval '7 days'
  order by l.created_at desc
  limit least(greatest(coalesce(p_limit, 12), 1), 30);
$$;

revoke all on function public.recent_activity(int) from public;
grant execute on function public.recent_activity(int) to anon, authenticated;

-- ─── submit_lead: accept promo_code ─────────────────────────────────────────
-- Re-declared with the promo field; body otherwise identical to 20261111090200_functions.sql.
create or replace function public.submit_lead(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id           uuid := coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid());
  v_phone        text := regexp_replace(coalesce(p ->> 'phone_number', ''), '[\s.()-]', '', 'g');
  v_parent       text := btrim(coalesce(p ->> 'parent_name', ''));
  v_student      text := btrim(coalesce(p ->> 'student_name', ''));
  v_age          int;
  v_course       text := p ->> 'course_code';
  v_branch       text := p ->> 'branch_location';
  v_promo        text := nullif(p ->> 'promo_code', '');
  v_date         date;
  v_existing     public.leads;
  v_row          public.leads;
  v_recent_count int;
begin
  if v_phone like '+84%' then
    v_phone := '0' || substr(v_phone, 4);
  end if;

  if v_phone !~ '^0[35789][0-9]{8}$' then
    raise exception 'Số điện thoại không hợp lệ' using hint = 'VALIDATION:phone_number';
  end if;
  if char_length(v_parent) not between 2 and 60 or v_parent ~ '[0-9]' then
    raise exception 'Họ tên phụ huynh không hợp lệ' using hint = 'VALIDATION:parent_name';
  end if;
  if char_length(v_student) not between 2 and 60 or v_student ~ '[0-9]' then
    raise exception 'Họ tên của bé không hợp lệ' using hint = 'VALIDATION:student_name';
  end if;
  begin
    v_age := (p ->> 'student_age')::int;
  exception when others then
    v_age := null;
  end;
  if v_age is null or v_age not between 3 and 12 then
    raise exception 'Tuổi của bé không hợp lệ' using hint = 'VALIDATION:student_age';
  end if;
  if not exists (select 1 from public.categories where code = v_course) then
    raise exception 'Khóa học không tồn tại' using hint = 'VALIDATION:course_code';
  end if;
  if not exists (select 1 from public.branches where code = v_branch) then
    raise exception 'Cơ sở không tồn tại' using hint = 'VALIDATION:branch_location';
  end if;
  if v_promo is not null and v_promo not in ('EBOOK_VAO_LOP_1') then
    raise exception 'Mã ưu đãi không hợp lệ' using hint = 'VALIDATION:promo_code';
  end if;
  if p ? 'preferred_date' and nullif(p ->> 'preferred_date', '') is not null then
    v_date := (p ->> 'preferred_date')::date;
    if v_date < current_date or v_date > current_date + 60 then
      raise exception 'Ngày học thử không hợp lệ' using hint = 'VALIDATION:preferred_date';
    end if;
  end if;

  select * into v_existing from public.leads where id = v_id;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  select * into v_existing
  from public.leads
  where phone_number = v_phone
    and course_code = v_course
    and lower(student_name) = lower(v_student)
    and created_at > now() - interval '30 minutes'
  order by created_at desc
  limit 1;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  select count(*) into v_recent_count
  from public.leads
  where phone_number = v_phone and created_at > now() - interval '24 hours';
  if v_recent_count >= 5 then
    raise exception 'Số điện thoại này đã đăng ký nhiều lần hôm nay' using hint = 'RATE_LIMITED';
  end if;

  insert into public.leads (
    id, parent_name, phone_number, student_name, student_age, course_code, branch_location,
    quiz_summary, preferred_date, preferred_slot, source, zalo_user_id, quiz_answers, promo_code
  ) values (
    v_id, v_parent, v_phone, v_student, v_age, v_course, v_branch,
    p -> 'quiz_summary',
    v_date,
    nullif(p ->> 'preferred_slot', ''),
    coalesce(nullif(p ->> 'source', ''), 'DIRECT'),
    nullif(p ->> 'zalo_user_id', ''),
    p -> 'quiz_answers',
    v_promo
  )
  returning * into v_row;

  return jsonb_build_object('id', v_row.id, 'code', v_row.code,
                            'created_at', v_row.created_at, 'duplicate', false);
end;
$$;

-- ───────────────── 20261113090000_video_publishing.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Video publishing by staff + share links + per-video lead attribution
--   storage bucket  feed-media         public read, staff-only write (videos + cover images)
--   videos          share_slug         short id for share links:  https://<web>/v/<share_slug>
--                   video_path / thumbnail_path / created_by
--   leads           source_ref         which video (id) brought this lead; source 'SHARE_LINK'
--   staff_video_stats()                leads per video, for the staff video list
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── Storage bucket ─────────────────────────────────────────────────────────
-- 200 MB per file here; the project-wide upload limit (Dashboard → Storage → Settings)
-- also applies — it is 50 MB on the Free plan.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'feed-media', 'feed-media', true, 209715200,
  array['video/mp4', 'video/quicktime', 'video/webm', 'image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Public bucket → anyone can read by URL. Only staff may write.
create policy "staff upload feed media"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'feed-media' and public.is_staff());

create policy "staff update feed media"
  on storage.objects for update to authenticated
  using (bucket_id = 'feed-media' and public.is_staff())
  with check (bucket_id = 'feed-media' and public.is_staff());

create policy "staff delete feed media"
  on storage.objects for delete to authenticated
  using (bucket_id = 'feed-media' and public.is_staff());

-- ─── videos: share slug + storage paths + author ───────────────────────────
alter table public.videos
  add column share_slug     text not null default substr(replace(gen_random_uuid()::text, '-', ''), 1, 10),
  add column video_path     text,
  add column thumbnail_path text,
  add column created_by     uuid default auth.uid() references auth.users (id) on delete set null;

alter table public.videos add constraint videos_share_slug_key unique (share_slug);
alter table public.videos add constraint videos_cta_text_len check (char_length(cta_text) between 3 and 80);

-- ─── leads: attribution ─────────────────────────────────────────────────────
alter table public.leads add column source_ref text check (source_ref is null or char_length(source_ref) <= 64);
create index leads_source_ref_idx on public.leads (source_ref) where source_ref is not null;

alter table public.leads drop constraint if exists leads_source_check;
alter table public.leads add constraint leads_source_check
  check (source in ('FEED', 'QUIZ', 'PORTFOLIO', 'DIRECT', 'SHARE_LINK'));

grant insert (source_ref) on public.leads to anon;

-- ─── staff_video_stats ──────────────────────────────────────────────────────
-- SECURITY INVOKER: non-staff see no leads (RLS) → all counts 0.
create or replace function public.staff_video_stats()
returns table (video_id uuid, lead_count bigint, last_lead_at timestamptz)
language sql
stable
security invoker
set search_path = public
as $$
  select v.id, count(l.id), max(l.created_at)
  from public.videos v
  left join public.leads l on l.source_ref = v.id::text
  group by v.id;
$$;

revoke all on function public.staff_video_stats() from public;
grant execute on function public.staff_video_stats() to authenticated;

-- ─── submit_lead: accept source_ref (+ SHARE_LINK source) ──────────────────
-- Re-declared; otherwise identical to 20261112090000_trust.sql.
create or replace function public.submit_lead(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id           uuid := coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid());
  v_phone        text := regexp_replace(coalesce(p ->> 'phone_number', ''), '[\s.()-]', '', 'g');
  v_parent       text := btrim(coalesce(p ->> 'parent_name', ''));
  v_student      text := btrim(coalesce(p ->> 'student_name', ''));
  v_age          int;
  v_course       text := p ->> 'course_code';
  v_branch       text := p ->> 'branch_location';
  v_promo        text := nullif(p ->> 'promo_code', '');
  v_source       text := coalesce(nullif(p ->> 'source', ''), 'DIRECT');
  v_source_ref   text := nullif(left(coalesce(p ->> 'source_ref', ''), 64), '');
  v_date         date;
  v_existing     public.leads;
  v_row          public.leads;
  v_recent_count int;
begin
  if v_phone like '+84%' then
    v_phone := '0' || substr(v_phone, 4);
  end if;

  if v_phone !~ '^0[35789][0-9]{8}$' then
    raise exception 'Số điện thoại không hợp lệ' using hint = 'VALIDATION:phone_number';
  end if;
  if char_length(v_parent) not between 2 and 60 or v_parent ~ '[0-9]' then
    raise exception 'Họ tên phụ huynh không hợp lệ' using hint = 'VALIDATION:parent_name';
  end if;
  if char_length(v_student) not between 2 and 60 or v_student ~ '[0-9]' then
    raise exception 'Họ tên của bé không hợp lệ' using hint = 'VALIDATION:student_name';
  end if;
  begin
    v_age := (p ->> 'student_age')::int;
  exception when others then
    v_age := null;
  end;
  if v_age is null or v_age not between 3 and 12 then
    raise exception 'Tuổi của bé không hợp lệ' using hint = 'VALIDATION:student_age';
  end if;
  if not exists (select 1 from public.categories where code = v_course) then
    raise exception 'Khóa học không tồn tại' using hint = 'VALIDATION:course_code';
  end if;
  if not exists (select 1 from public.branches where code = v_branch) then
    raise exception 'Cơ sở không tồn tại' using hint = 'VALIDATION:branch_location';
  end if;
  if v_promo is not null and v_promo not in ('EBOOK_VAO_LOP_1') then
    raise exception 'Mã ưu đãi không hợp lệ' using hint = 'VALIDATION:promo_code';
  end if;
  if v_source not in ('FEED', 'QUIZ', 'PORTFOLIO', 'DIRECT', 'SHARE_LINK') then
    raise exception 'Nguồn không hợp lệ' using hint = 'VALIDATION:source';
  end if;
  if p ? 'preferred_date' and nullif(p ->> 'preferred_date', '') is not null then
    v_date := (p ->> 'preferred_date')::date;
    if v_date < current_date or v_date > current_date + 60 then
      raise exception 'Ngày học thử không hợp lệ' using hint = 'VALIDATION:preferred_date';
    end if;
  end if;

  select * into v_existing from public.leads where id = v_id;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  select * into v_existing
  from public.leads
  where phone_number = v_phone
    and course_code = v_course
    and lower(student_name) = lower(v_student)
    and created_at > now() - interval '30 minutes'
  order by created_at desc
  limit 1;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  select count(*) into v_recent_count
  from public.leads
  where phone_number = v_phone and created_at > now() - interval '24 hours';
  if v_recent_count >= 5 then
    raise exception 'Số điện thoại này đã đăng ký nhiều lần hôm nay' using hint = 'RATE_LIMITED';
  end if;

  insert into public.leads (
    id, parent_name, phone_number, student_name, student_age, course_code, branch_location,
    quiz_summary, preferred_date, preferred_slot, source, source_ref, zalo_user_id, quiz_answers, promo_code
  ) values (
    v_id, v_parent, v_phone, v_student, v_age, v_course, v_branch,
    p -> 'quiz_summary',
    v_date,
    nullif(p ->> 'preferred_slot', ''),
    v_source,
    v_source_ref,
    nullif(p ->> 'zalo_user_id', ''),
    p -> 'quiz_answers',
    v_promo
  )
  returning * into v_row;

  return jsonb_build_object('id', v_row.id, 'code', v_row.code,
                            'created_at', v_row.created_at, 'duplicate', false);
end;
$$;

